WITH base AS (SELECT *, FLOOR(discount_pct) AS discount_pct_whole, DATEDIFF(ends_on, starts_on) AS days_starts_on_to_ends_on FROM promotions WHERE ends_on > TO_DATE('2023-11-09')), latest AS (SELECT * FROM base QUALIFY RANK() OVER (PARTITION BY promo_code, channel ORDER BY starts_on DESC) = 1), attributed AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM latest a LEFT JOIN promotions pr ON a.channel = pr.channel AND a.starts_on BETWEEN pr.starts_on AND pr.ends_on), with_window AS (SELECT e.*, pr.id AS promo_id_2, pr.promo_code AS promotion_promo_code_2, pr.discount_pct AS promotion_discount_pct_2 FROM attributed e LEFT JOIN promotions pr ON e.channel <=> pr.channel AND e.starts_on >= pr.starts_on AND e.starts_on < pr.ends_on + INTERVAL '30' DAY), matched AS (SELECT a.*, pr.id AS promo_id_3, pr.promo_code AS promotion_promo_code_3, pr.discount_pct AS promotion_discount_pct_3 FROM with_window a LEFT JOIN promotions pr ON a.channel = pr.channel AND a.ends_on BETWEEN pr.starts_on AND pr.ends_on) SELECT * FROM (SELECT promotion_promo_code_3, promotion_promo_code, promotion_promo_code_2, discount_pct FROM matched) src PIVOT (SUM(discount_pct) FOR promotion_promo_code_2 IN ('BUNDLE' AS bundle, 'WELCOME5' AS welcome5))
